require_once __DIR__.'/inc/ai/Bootstrap.php';header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');
if(!isUser()){redirect('/index.php?action=login');exit;}$project=ModuleProjectAccess::select($_GET['project']??$_SESSION['project_id']??'');if(!AiAccess::pageAllowed())AccessControl::deny();$principal=AiAccess::principal($project);$pid=$project['id'];$canWrite=ModuleProjectAccess::allowed('products','products','ai_connect','use');$store=new AiStore();$hub=new AiHub($store);$social=new AiSocial($store);$error='';$message=isset($_GET['connected'])?'اتصال گوگل تکمیل شد؛ دریافت دستی یا Cron را اجرا کنید.':'';$newSource=null;$salesReport=null;
