if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){RequestSecurity::enforce();try{AiAccess::write();$action=$_POST['action']??'';if($action==='source'){$newSource=$hub->createSource($project,$principal,$_POST);$message='منبع ساخته شد؛ توکن فقط همین بار نمایش داده می‌شود.';}
elseif($action==='connection_test'){$result=(new IntegrationHealth($store))->probe($project,$principal,$_POST['platform']??'');$message=$result['success']?'تست خواندن اتصال موفق بود؛ جزئیات در تب سلامت اتصال‌ها ثبت شد.':($result['error']??'تست موفق نبود.');}
elseif($action==='sales_report'){$salesReport=(new HubReports($store))->sales($project,$_POST);}
elseif($action==='composio_config'){(new ComposioBridge($store))->configure($project,$principal,$_POST);$message='اتصال پروژه‌ای Composio ذخیره شد؛ دریافت واقعی را تست کنید.';}
elseif($action==='composio_pull'){$source=$hub->source($project,$_POST['source_id']??'');$result=(new ComposioBridge($store))->pull($source,$_POST['from']??'',$_POST['to']??'',(int)($_POST['offset']??0));$message='Composio: '.$result['accepted'].' ردیف واقعی دریافت شد؛ ادامه: '.($result['next_offset']??'پایان');}
elseif($action==='disable'){$hub->disable($project,$principal,$_POST['id']??'');$message='اتصال منبع متوقف شد؛ دادهٔ قبلی برای بررسی باقی ماند.';}
elseif($action==='import'){$source=$hub->source($project,$_POST['source_id']??'');$rows=json_decode($_POST['rows']??'',true);$result=$hub->ingest($project,$source,$_POST['kind']??'',$rows,$_POST['batch_id']??'',false);$message=$result['accepted'].' ردیف ثبت/به‌روز شد؛ شناسه‌های تکراری محصول تازه نمی‌سازند.';}
elseif($action==='google'){$url=(new AiGoogle($store))->configure($project,$principal,$_POST);header('Location: '.$url);exit;}
elseif($action==='google_pull'){$source=$hub->source($project,$_POST['source_id']??'');$result=(new AiGoogle($store))->pull($source,$_POST['kind']??'',$_POST['from']??'',$_POST['to']??'',(int)($_POST['offset']??0));$message='دریافت شد: '.$result['accepted'].' ردیف؛ '.($result['next_offset']===null?'بازه تکمیل شد.':'برای ادامه offset='.$result['next_offset']);}
elseif($action==='social_cancel'){$social->cancel($project,$_POST['id']??'');$message='انتشار در صف لغو شد.';}
elseif($action==='social_route'){AiAccess::need('settings','use');$platform=$_POST['platform']??'';if(!in_array($platform,['telegram','instagram'],true))throw new RuntimeException('کانال معتبر نیست.');$project['settings']['connections'][$platform]['proxy']['bypass_method']='chatgpt';$project['settings']['connections'][$platform]['chatgpt_destination']=mb_substr(trim($_POST['destination']??''),0,200);saveProject($project);$message='روش ChatGPT برای این کانال فعال شد؛ صف انتشار نیازمند ابزار متصل و رسید واقعی است.';}
else throw new RuntimeException('عملیات معتبر نیست.');}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'عملیات انجام نشد.';}}
$health=(new IntegrationHealth($store))->overview($project);$sources=$hub->sources($project);$selected=$_GET['source']??($sources[0]['id']??'');$kind=$_GET['kind']??'';$source=null;foreach($sources as $r)if($r['id']===$selected)$source=$r;if($source&&!in_array($kind,$source['kinds'],true))$kind=$source['kinds'][0];$filters=array_filter(['from'=>$_GET['from']??'','to'=>$_GET['to']??'','currency'=>$_GET['currency']??'','grain'=>$_GET['grain']??'']);$page=max(1,(int)($_GET['page']??1));$data=null;$stats=null;if($source)try{$data=$hub->read($project,$selected,$kind,$filters,($page-1)*25,25);$stats=$hub->stats($project,$selected,$kind,$filters);}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مرکز داده و انتشار هوشمند</title><link rel="stylesheet" href="/panel/assets/ai-connect.css?v=1"><style>.hub-scroll{overflow:auto}table{border-collapse:collapse;min-width:650px;width:100%;font-size:12px}td,th{padding:12px;border-bottom:1px solid #ced8d2;text-align:right;max-width:320px;overflow-wrap:anywhere}.hub-preview{max-height:420px}.hub-scroll a{white-space:nowrap}</style><?php if(!$canWrite):?><style>form[method="post"]{display:none}</style><?php endif;?></head><body><main class="ai-shell"><header class="ai-header"><div><p class="ai-eyebrow"><?=hub_h($project['name'])?></p><h1>مرکز داده و انتشار هوشمند</h1><p>وردپرس، فروشگاه‌ها، CRM، فروش، سئو و شبکه‌های اجتماعی در یک مسیر پروژه‌ای</p></div><a href="/panel/ai-connect.php?project=<?=hub_h($pid)?>">اتصال ChatGPT و گزارش‌ها ←</a></header><?php if($error):?><p class="ai-alert error" role="alert"><?=hub_h($error)?></p><?php endif;?><?php if($message):?><p class="ai-alert" role="status"><?=hub_h($message)?></p><?php endif;?>
