<section class="ai-card" id="hub-reports"><h2>گزارش تفکیکی و تجمیعی فروش</h2><form method="post"><input type="hidden" name="action" value="sales_report"><fieldset><legend>یک منبع مرجع برای هر فروشگاه</legend><?php foreach($sources as $r):if(!in_array('sales',$r['kinds'],true))continue;?><label class="ai-check"><input type="checkbox" name="sources[]" value="<?=hub_h($r['id'])?>"><?=hub_h($r['name'].' / '.$r['store_id'])?></label><?php endforeach;?></fieldset><div class="ai-grid"><label>ارز<input name="currency" required value="IRR"></label><label>سطح<select name="grain"><option value="order">سفارش</option><option value="day">جمع روزانه</option></select></label><label>تفکیک<select name="group"><option value="store">فروشگاه</option><option value="day">روز</option><option value="month">ماه</option></select></label><label>از<input type="date" name="from"></label><label>تا<input type="date" name="to"></label></div><button>ساخت گزارش</button></form><?php if($salesReport):?><p>جمع خالص: <?=number_format($salesReport['totals']['net'],2)?> <?=hub_h($salesReport['currency'])?></p><pre><?=hub_h(json_encode($salesReport,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT))?></pre><?php endif;?><p>منابع هم‌پوشان یک فروشگاه، ارزهای مختلف و سفارش/جمع روزانه با هم جمع نمی‌شوند. CTR و رتبه و کاربران یکتا نیز جمع ساده ندارند.</p></section>
