<?php if($data):?><p><?=number_format($data['total'])?> رکورد · منبع: <?=hub_h($data['origin'])?> · آخرین دریافت: <?=!empty($data['updated_at'])?hub_h(date('Y/m/d H:i',$data['updated_at'])):'هنوز دریافتی نیست'?></p><p class="ai-muted">منابعی که سفارش یا روز فروش مشترک دارند با هم جمع نمی‌شوند. وضعیت سفارش و مرجوعی از منبع حفظ می‌شود. موجودی این بخش شاهد منبع است؛ بدون تطبیق و تأیید، موجودی ERP یا تصاویر کتابخانه را بازنویسی نمی‌کند.</p><div class="ai-grid"><?php foreach($stats['sales_by_currency_and_grain'] as $group=>$total):?><div class="ai-card"><b><?=hub_h($group)?></b><p>خالص: <?=number_format($total['net'],2)?> · ناخالص: <?=number_format($total['gross'],2)?></p><p>مرجوعی: <?=number_format($total['refund'],2)?> · سفارش: <?=number_format($total['orders'])?></p></div><?php endforeach;?><?php if(in_array($kind,['products','posts','pages'],true)):?><div class="ai-card"><h3>نقص متادیتای سئو</h3><p>بدون عنوان SEO: <?=$stats['seo_issues']['missing_seo_title']?> · بدون توضیح: <?=$stats['seo_issues']['missing_seo_description']?></p><p>Noindex: <?=$stats['seo_issues']['noindex']?> · بدون تصویر: <?=$stats['seo_issues']['missing_image']?></p><small>خالی‌بودن متادیتا ممکن است با قالب افزونه جبران شود؛ این گزارش رتبهٔ گوگل یا نمرهٔ ساختگی نیست.</small></div><?php endif;?></div><div class="hub-scroll hub-preview"><table><thead><tr><th>شناسه</th><th>نام / عنوان / صفحه</th><th>تاریخ / وضعیت</th><th>دادهٔ منبع</th></tr></thead><tbody><?php foreach($data['rows'] as $r):?><tr><td><?=hub_h($r['id'])?></td><td><?=hub_h($r['name']??$r['title']??$r['page']??$r['sku']??'—')?></td><td><?=hub_h($r['date']??$r['status']??$r['modified_at']??'—')?></td><td><details><summary>مشاهده</summary><pre><?=hub_h(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details></td></tr><?php endforeach;?></tbody></table></div><nav class="ai-actions" aria-label="صفحه‌بندی داده"><?php if($page>1):?><a href="?<?=hub_h(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">صفحه قبل</a><?ph